namespace gui_forms {

// FlowLayoutPanelCompat's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/flow_layout_panel_compat.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The direction children follow one another: left to right, right to left, top down or bottom up.
template <typename Declaring>
struct FlowLayoutDirectionCapability {
    PropertyCell<FlowDirection, FlowLayoutDirectionCapability<Declaring>> flow_direction{FlowDirection::left_to_right};

    static void assign(FlowLayoutDirectionCapability& capability, FlowDirection incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.flow_direction), incoming);
        if (!capability.flow_direction.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.flow_direction));
    }
};

// Whether a child that does not fit the rest of the line starts a new one.
template <typename Declaring>
struct FlowLayoutWrapContentsCapability {
    PropertyCell<bool, FlowLayoutWrapContentsCapability<Declaring>> wrap_contents{true};

    static void assign(FlowLayoutWrapContentsCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.wrap_contents), incoming);
        if (!capability.wrap_contents.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.wrap_contents));
    }
};

// The space between items along a line (width) and between lines (height); each finite and between zero and 256, else std::invalid_argument.
template <typename Declaring>
struct FlowLayoutItemSpacingCapability {
    PropertyCell<Size, FlowLayoutItemSpacingCapability<Declaring>> item_spacing{Size{}};

    static void assign(FlowLayoutItemSpacingCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_spacing), incoming);
        if (!capability.item_spacing.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_spacing));
    }
};

// How a line's items share its free space along the flow (std::invalid_argument outside the enumeration).
template <typename Declaring>
struct FlowLayoutMainAlignmentCapability {
    PropertyCell<FlowMainAlignment, FlowLayoutMainAlignmentCapability<Declaring>> main_alignment{FlowMainAlignment::start};

    static void assign(FlowLayoutMainAlignmentCapability& capability, FlowMainAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.main_alignment), incoming);
        if (!capability.main_alignment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.main_alignment));
    }
};

// Where an item sits across its line: start, center, end or stretched (std::invalid_argument outside them).
template <typename Declaring>
struct FlowLayoutCrossAlignmentCapability {
    PropertyCell<FlowCrossAlignment, FlowLayoutCrossAlignmentCapability<Declaring>> cross_alignment{FlowCrossAlignment::start};

    static void assign(FlowLayoutCrossAlignmentCapability& capability, FlowCrossAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.cross_alignment), incoming);
        if (!capability.cross_alignment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.cross_alignment));
    }
};

// FlowDirection as a property value; defined beside FlowLayoutPanelCompat's table.
template <>
struct PropertyValueTraits<FlowDirection> {
    static PropertyType type();
    static BindingValue to_binding(FlowDirection value);
    static FlowDirection from_binding(const BindingValue& value);
};

// FlowMainAlignment as a property value; defined beside FlowLayoutPanelCompat's table.
template <>
struct PropertyValueTraits<FlowMainAlignment> {
    static PropertyType type();
    static BindingValue to_binding(FlowMainAlignment value);
    static FlowMainAlignment from_binding(const BindingValue& value);
};

// FlowCrossAlignment as a property value; defined beside FlowLayoutPanelCompat's table.
template <>
struct PropertyValueTraits<FlowCrossAlignment> {
    static PropertyType type();
    static BindingValue to_binding(FlowCrossAlignment value);
    static FlowCrossAlignment from_binding(const BindingValue& value);
};

// Every FlowLayoutPanelCompat capability, in the order the declaring class takes them.
template <typename Declaring>
struct FlowLayoutPanelCompatCapabilities : public FlowLayoutDirectionCapability<Declaring>,
                                           public FlowLayoutWrapContentsCapability<Declaring>,
                                           public FlowLayoutItemSpacingCapability<Declaring>,
                                           public FlowLayoutMainAlignmentCapability<Declaring>,
                                           public FlowLayoutCrossAlignmentCapability<Declaring> {};

} // namespace gui_forms
